1: //! R3 反向对照：`now_ms` 只允许有一个实现，且落在 `src/clock.rs`（docs/01 §2.3.1 E63）。
2: //!
3: //! 收敛前有九个模块各写一份逐字同义的 `now_ms()`，谁都能再抄一份。这条用例把
4: //! 「只有一份」变成可执行的判据：往 `src/` 里贴回第二份、或把唯一的出口删掉，都会红。
5: //!
6: //! 探针字符串在运行时拼接，避免用例自己命中自己（本文件就在 `tests/` 下）。
7: 
8: use std::fs;
9: use std::path::{Path, PathBuf};
10: 
11: /// `tests/` 下允许存在的同名实现，必须在此登记并写明理由。
12: ///
13: /// 这不是「漏网名单」：`evals_baseline.rs` 那份返回 `u128` 且时钟早于 1970 时 panic，
14: /// 与 `clock::now_ms`（`u64`、回落 0）类型与失败语义都不同，R3 明确不合并。
15: const TESTS_EXEMPT: &[(&str, &str)] = &[(
16:     "tests/evals_baseline.rs",
17:     "返回 u128 且时钟早于 1970 时 panic，与 clock::now_ms 的 u64/回落 0 语义不同，R3 决定不合并",
18: )];
19: 
20: fn collect_rs(dir: &Path, out: &mut Vec<PathBuf>) {
21:     let Ok(entries) = fs::read_dir(dir) else { return };
22:     for entry in entries.flatten() {
23:         let path = entry.path();
24:         if path.is_dir() {
25:             collect_rs(&path, out);
26:         } else if path.extension().and_then(|ext| ext.to_str()) == Some("rs") {
27:             out.push(path);
28:         }
29:     }
30: }
31: 
32: /// 文件里是否有一行**代码**（非行注释）定义了 `now_ms`。
33: fn defines_now_ms(path: &Path) -> bool {
34:     // 拼成 "fn now_ms("：分开写是为了让本文件自己不含这串字面量（否则会命中自己）。
35:     let needle = ["fn", "now_ms("].join(" ");
36:     let Ok(text) = fs::read_to_string(path) else { return false };
37:     text.lines().any(|line| {
38:         let trimmed = line.trim_start();
39:         !trimmed.starts_with("//") && trimmed.contains(&needle)
40:     })
41: }
42: 
43: /// 扫描目录，返回定义 `now_ms` 的文件（相对仓库内的 `src-tauri` 根，正斜杠）。
44: fn files_defining(dir: &Path, manifest_dir: &Path) -> Vec<String> {
45:     let mut all = Vec::new();
46:     collect_rs(dir, &mut all);
47:     let mut found: Vec<String> = all
48:         .into_iter()
49:         .filter(|path| defines_now_ms(path))
50:         .map(|path| {
51:             path.strip_prefix(manifest_dir)
52:                 .unwrap_or(&path)
53:                 .to_string_lossy()
54:                 .replace('\\', "/")
55:         })
56:         .collect();
57:     found.sort();
58:     found
59: }
60: 
61: /// 扫描本身不能是空的：目录读不到或扩展名过滤写错时，上面两条断言会假绿。
62: #[test]
63: fn scan_is_not_vacuous() {
64:     let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
65:     let mut src = Vec::new();
66:     collect_rs(&manifest_dir.join("src"), &mut src);
67:     let mut tests = Vec::new();
68:     collect_rs(&manifest_dir.join("tests"), &mut tests);
69:     assert!(src.len() > 50, "没扫到 src/ 的源码（{} 个），用例会假绿", src.len());
70:     assert!(!tests.is_empty(), "没扫到 tests/ 的源码，用例会假绿");
71: }
72: 
73: #[test]
74: fn src_has_exactly_one_now_ms() {
75:     let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
76:     let found = files_defining(&manifest_dir.join("src"), manifest_dir);
77:     // 改坏方式示例：在任一模块里贴回 `fn now_ms() -> u64 { ... }`，这里立刻多一项。
78:     assert_eq!(
79:         found,
80:         vec!["src/clock.rs".to_string()],
81:         "src/ 下 now_ms 必须只有 src/clock.rs 一处实现，实际：{found:?}"
82:     );
83: }
84: 
85: #[test]
86: fn tests_only_have_registered_now_ms() {
87:     let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
88:     let found = files_defining(&manifest_dir.join("tests"), manifest_dir);
89:     let mut expected: Vec<String> = TESTS_EXEMPT.iter().map(|(path, _)| (*path).to_string()).collect();
90:     expected.sort();
91:     // 双向断言：既不许新增私货，也不许为了让用例变绿把豁免那份删掉/合并掉。
92:     assert_eq!(
93:         found, expected,
94:         "tests/ 下的 now_ms 必须与豁免登记逐一对应，实际：{found:?}"
95:     );
96:     for (path, reason) in TESTS_EXEMPT {
97:         assert!(
98:             !reason.trim().is_empty(),
99:             "tests/ 豁免 {path} 必须写明不合并的理由"
100:         );
101:     }
102: }

