1: //! 全仓唯一的「当前时间」出口（docs/01 §2.3.1 E63）。
2: //!
3: //! R3：收敛前有九个模块各写一份 `now_ms()`，语义逐字相同（UNIX 纪元毫秒、`u64`、
4: //! 时钟早于 1970 回落 0），只是闭包变量名和 `unwrap_or` 写法不同。现在只留这一份。
5: //!
6: //! 本模块是纯叶子，只依赖 `std`；任何模块依赖它都不产生反向依赖。
7: 
8: use std::time::{SystemTime, UNIX_EPOCH};
9: 
10: /// 当前 UNIX 纪元毫秒。
11: ///
12: /// 时钟早于 1970（系统时间被拨回）时返回 0 而不是 panic：调用方都是给时间戳字段赋值
13: /// （`at_ms` / `created_at_ms` / `granted_at_ms` / 作业 id …），返回 0 只影响展示，
14: /// panic 会连带拖垮整条会话或作业链路。这条回落语义与收敛前逐字一致。
15: pub fn now_ms() -> u64 {
16:     SystemTime::now()
17:         .duration_since(UNIX_EPOCH)
18:         .map(|d| d.as_millis() as u64)
19:         .unwrap_or(0)
20: }
21: 
22: #[cfg(test)]
23: mod tests {
24:     use super::*;
25: 
26:     /// 2024-01-01T00:00:00Z，早于它的结果只能是「秒级误用」或「回落 0」。
27:     const LOWER: u64 = 1_704_067_200_000;
28:     /// 2100-01-01T00:00:00Z，晚于它说明单位或时基被改坏。
29:     const UPPER: u64 = 4_102_444_800_000;
30: 
31:     #[test]
32:     fn now_ms_is_epoch_milliseconds() {
33:         let t = now_ms();
34:         assert!(
35:             t > LOWER,
36:             "now_ms 不是毫秒级纪元时间戳（疑似改成秒或返回 0）：{t}"
37:         );
38:         assert!(t < UPPER, "now_ms 超出合理区间，时基可能被改坏：{t}");
39:     }
40: 
41:     #[test]
42:     fn now_ms_never_goes_backwards() {
43:         let first = now_ms();
44:         let second = now_ms();
45:         assert!(second >= first, "now_ms 回退：{first} → {second}");
46:     }
47: }

