1: //! 派生索引库的 schema 归属与安全打开（SH-113）。
2: //!
3: //! 上游 `session-query-sqlite/src/schema.ts` 的 Rust 等价：
4: //! - application id + schema version 归属校验；
5: //! - 只认领空库或**已识别的** SHANIU 派生索引，绝不清空不认识的库；
6: //! - 版本不匹配的已识别派生索引原地重置（只 DROP 认识的表），文件本身不删；
7: //! - 文件缺失或真损坏才安全重建（损坏件**改名保留**，不误删、不改写任何 rollout 档案）。
8: 
9: use std::collections::HashSet;
10: use std::fs;
11: use std::path::{Path, PathBuf};
12: use std::time::{Duration, SystemTime, UNIX_EPOCH};
13: 
14: use rusqlite::{Connection, Transaction};
15: 
16: use crate::session_query::SearchError;
17: 
18: /// 索引连接的忙等待上限（2026-11-11）。派生索引会被第二个实例并发访问。
19: /// rusqlite 0.37 的 `Connection::open` 默认已设 5000ms；这里显式写出来不是"从 0 改成 5 秒"，
20: /// 而是不依赖依赖库默认值（升级后可能漂移）。5 秒覆盖一次对账事务的正常时长，
21: /// 超过 5 秒说明另一方卡死，报错比无限等更好。
22: const BUSY_TIMEOUT: Duration = Duration::from_secs(5);
23: 
24: /// SHANIU 派生索引的 application id（"SHNQ"）。
25: /// 刻意**不共用**上游 DSH 的 `0x44534851`：两侧 schema 不同，共用会让上游库
26: /// 被误认成"我们的旧版本"而原地 DROP——那正是上游"只 reset 认识的派生 schema"
27: /// 要防的事故。
28: pub const APPLICATION_ID: i64 = 0x5348_4e51;
29: /// SHANIU 派生索引的 schema 版本；不兼容版本原地重置。
30: ///
31: /// v2：`surface` 不再恒为 `current`——被压缩锚点取代的原文记 `shadowed`
32: /// （能搜到，但模型当前不再看到）。旧索引里的 `current` 已经失真，
33: /// 必须靠版本号强制重建，而不是等档案下次变化才顺手修正。
34: pub const SCHEMA_VERSION: i64 = 2;
35: 
36: /// 认识的用户表（含 FTS5 的 shadow 表）。出现任何未知表即拒绝，绝不 DROP 别人的数据。
37: const DERIVED_USER_TABLES: &[&str] = &[
38:     "search_state",
39:     "persisted_sessions",
40:     "persisted_docs",
41:     "persisted_docs_data",
42:     "persisted_docs_idx",
43:     "persisted_docs_content",
44:     "persisted_docs_docsize",
45:     "persisted_docs_config",
46: ];
47: 
48: /// 对既有文件的分类结果。
49: enum Existing {
50:     /// 校验通过，可直接用（可能已做过原地版本重置）。
51:     Ready(Connection),
52:     /// 不认识的库 / 别人的库：**拒绝**，文件一个字节都不动。
53:     Rejected(String),
54:     /// 真损坏（打不开 / PRAGMA 读失败）：允许安全重建。
55:     Corrupt(String),
56: }
57: 
58: /// 打开、校验并初始化索引。这是 `first-search` 惰性打开的唯一入口。
59: pub fn open_index(path: &Path) -> Result<Connection, SearchError> {
60:     if let Some(parent) = path.parent() {
61:         fs::create_dir_all(parent).map_err(|e| {
62:             SearchError::IndexFailed(format!("创建索引目录失败 {}: {e}", parent.display()))
63:         })?;
64:     }
65:     let existing = if path.exists() {
66:         classify_existing(path)
67:     } else {
68:         Existing::Corrupt("索引文件不存在".to_string())
69:     };
70:     let mut conn = match existing {
71:         Existing::Ready(conn) => conn,
72:         Existing::Rejected(reason) => return Err(SearchError::IndexFailed(reason)),
73:         Existing::Corrupt(reason) => {
74:             tracing::debug!("派生索引 {} 将安全重建：{reason}", path.display());
75:             if path.exists() {
76:                 // 保守重建：损坏件改名保留，绝不 unlink 一个可能是别人的数据。
77:                 quarantine(path)?;
78:             }
79:             let conn = Connection::open(path).map_err(|e| {
80:                 SearchError::IndexFailed(format!("新建派生索引失败 {}: {e}", path.display()))
81:             })?;
82:             conn.busy_timeout(BUSY_TIMEOUT).map_err(|e| {
83:                 SearchError::IndexFailed(format!("设置新建索引忙等待失败 {}: {e}", path.display()))
84:             })?;
85:             conn.execute_batch(&format!("PRAGMA application_id = {APPLICATION_ID};"))
86:                 .map_err(|e| SearchError::IndexFailed(format!("写入 application id 失败: {e}")))?;
87:             conn
88:         }
89:     };
90:     // 先配连接参数再碰 schema：下面的 DDL 与对账都要经过写锁，忙等待必须在它们之前生效。
91:     configure_connection(&conn, path)?;
92:     ensure_persistent_schema(&mut conn)?;
93:     ensure_temp_schema(&conn)?;
94:     Ok(conn)
95: }
96: 
97: /// 连接参数：忙等待 + WAL（2026-11-11）。
98: ///
99: /// `busy_timeout` 必须每条连接都设（SQLite 是 per-connection 语义），包括
100: /// `classify_existing` 里那条——否则双开时归属校验会在争用下被判成 "Corrupt"，
101: /// 进而尝试 quarantine 一个其实健康的库。
102: ///
103: /// WAL 让读不阻塞写、写不阻塞读，正是双开搜索的场景。设不上（网络盘等不支持 WAL 的
104: /// 文件系统）只记 warn 继续用当前模式：派生索引可用性优先于模式偏好，不为一个
105: /// 模式选择让搜索整体不可用。WAL 的 `-wal/-shm` 残留由 `quarantine` 一并改名带走。
106: fn configure_connection(conn: &Connection, path: &Path) -> Result<(), SearchError> {
107:     conn.busy_timeout(BUSY_TIMEOUT).map_err(|e| {
108:         SearchError::IndexFailed(format!("设置索引忙等待失败 {}: {e}", path.display()))
109:     })?;
110:     match conn.query_row("PRAGMA journal_mode = WAL", [], |row| row.get::<_, String>(0)) {
111:         Ok(mode) if mode.eq_ignore_ascii_case("wal") => {}
112:         Ok(mode) => tracing::warn!(
113:             path = %path.display(),
114:             mode = %mode,
115:             "派生索引未进入 WAL 模式，继续使用当前模式"
116:         ),
117:         Err(error) => tracing::warn!(
118:             path = %path.display(),
119:             %error,
120:             "派生索引切换 WAL 失败，继续使用当前模式"
121:         ),
122:     }
123:     Ok(())
124: }
125: 
126: /// 校验既有文件归属。只读 PRAGMA 与 sqlite_master；除"认识的版本不匹配原地重置"外不写。
127: fn classify_existing(path: &Path) -> Existing {
128:     let conn = match Connection::open(path) {
129:         Ok(conn) => conn,
130:         Err(e) => return Existing::Corrupt(format!("打不开: {e}")),
131:     };
132:     // 与 open_index 同一条忙等待口径：这里的读不该被另一个实例的写瞬间打回 BUSY，
133:     // 否则"争用"会被误判成"文件损坏"并触发 quarantine。
134:     if let Err(e) = conn.busy_timeout(BUSY_TIMEOUT) {
135:         return Existing::Corrupt(format!("设置忙等待失败: {e}"));
136:     }
137:     let application_id = match pragma_i64(&conn, "PRAGMA application_id") {
138:         Ok(value) => value,
139:         Err(e) => return Existing::Corrupt(format!("读 application_id 失败: {e}")),
140:     };
141:     let version = match pragma_i64(&conn, "PRAGMA user_version") {
142:         Ok(value) => value,
143:         Err(e) => return Existing::Corrupt(format!("读 user_version 失败: {e}")),
144:     };
145:     let tables = match list_user_tables(&conn) {
146:         Ok(tables) => tables,
147:         Err(e) => return Existing::Corrupt(format!("读 sqlite_master 失败: {e}")),
148:     };
149: 
150:     if application_id != 0 && application_id != APPLICATION_ID {
151:         return Existing::Rejected(format!(
152:             "索引路径 {} 属于其它应用（application_id={application_id}），拒绝改写；请另选路径或手动移除该文件",
153:             path.display()
154:         ));
155:     }
156:     if application_id == 0 && !tables.is_empty() {
157:         return Existing::Rejected(format!(
158:             "索引路径 {} 不是空库或可识别的 SHANIU 派生索引（含 {} 张用户表），拒绝改写",
159:             path.display(),
160:             tables.len()
161:         ));
162:     }
163:     if application_id == APPLICATION_ID {
164:         let unknown: Vec<&String> = tables
165:             .iter()
166:             .filter(|name| !DERIVED_USER_TABLES.contains(&name.as_str()))
167:             .collect();
168:         if !unknown.is_empty() {
169:             return Existing::Rejected(format!(
170:                 "派生索引 {} 含未识别的用户表（{}），拒绝原地重置",
171:                 path.display(),
172:                 unknown.iter().map(|s| s.as_str()).collect::<Vec<_>>().join(", ")
173:             ));
174:         }
175:         if version != SCHEMA_VERSION {
176:             // 只 DROP 认识的表，随后由 ensure_persistent_schema 按当前版本重建。
177:             if let Err(e) = reset_derived_schema(&conn, &tables) {
178:                 return Existing::Rejected(format!("重置旧版本派生索引失败: {e}"));
179:             }
180:         }
181:     }
182:     Existing::Ready(conn)
183: }
184: 
185: fn pragma_i64(conn: &Connection, sql: &str) -> Result<i64, rusqlite::Error> {
186:     conn.query_row(sql, [], |row| row.get(0))
187: }
188: 
189: fn list_user_tables(conn: &Connection) -> Result<Vec<String>, rusqlite::Error> {
190:     let mut stmt = conn.prepare(
191:         "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT GLOB 'sqlite_*' ORDER BY name",
192:     )?;
193:     let rows = stmt.query_map([], |row| row.get::<_, String>(0))?;
194:     let mut out = Vec::new();
195:     for row in rows {
196:         out.push(row?);
197:     }
198:     Ok(out)
199: }
200: 
201: fn reset_derived_schema(conn: &Connection, tables: &[String]) -> Result<(), rusqlite::Error> {
202:     for name in tables {
203:         // 表名来自 sqlite_master 且先经过白名单校验，用双引号包裹后不含可执行 SQL。
204:         conn.execute(&format!("DROP TABLE IF EXISTS \"{}\"", name.replace('"', "\"\"")), [])?;
