228: /// 把损坏的索引文件改名保留（含 WAL/SHM/journal 附属），再让调用方新建。
229: /// 目标是"不误删"，所以 rename 失败一律报错而不是强行覆盖。
230: fn quarantine(path: &Path) -> Result<(), SearchError> {
231:     let stamp = now_ms();
232:     let name = path
233:         .file_name()
234:         .map(|n| n.to_string_lossy().into_owned())
235:         .unwrap_or_else(|| "session-search.db".to_string());
236:     let mut counter = 0u32;
237:     let target: PathBuf;
238:     loop {
239:         let suffix = if counter == 0 {
240:             format!("{name}.corrupt-{}-{stamp}", std::process::id())
241:         } else {
242:             format!("{name}.corrupt-{}-{stamp}-{counter}", std::process::id())
243:         };
244:         let candidate = path.with_file_name(suffix);
245:         if !candidate.exists() {
246:             target = candidate;
247:             break;
248:         }
249:         counter += 1;
250:     }
251:     fs::rename(path, &target).map_err(|e| {
252:         SearchError::IndexFailed(format!(
253:             "损坏索引改名保留失败 {} → {}: {e}（不删除原文件）",
254:             path.display(),
255:             target.display()
256:         ))
257:     })?;
258:     // 附属文件尽力一并移走；残留不阻断重建，但绝不主动删除。
259:     for suffix in ["-wal", "-shm", "-journal"] {
260:         let mut side = path.as_os_str().to_os_string();
261:         side.push(suffix);
262:         let side = PathBuf::from(side);
263:         if side.exists() {
264:             let mut side_target = target.as_os_str().to_os_string();
265:             side_target.push(suffix);
266:             let _ = fs::rename(&side, PathBuf::from(side_target));
267:         }
268:     }
269:     prune_quarantined(&target, &name);
270:     Ok(())
271: }
272: 
273: /// 隔离件文件名里的毫秒时间戳：`{name}.corrupt-{pid}-{stamp}[-{counter}]`。
274: ///
275: /// 不能用 mtime 排序：`rename` 会保留原文件的修改时间，一份「今天刚改名」的隔离件
276: /// 可能带着几个月前的 mtime —— 按 mtime 会把第一次损坏的现场误判成最新的，
277: /// 恰好把要保的那份删掉。文件名里的 stamp 才是隔离发生的真实先后。
278: fn quarantine_stamp(file_name: &str, prefix: &str) -> Option<u128> {
279:     let rest = file_name.strip_prefix(prefix)?;
280:     let mut parts = rest.split('-');
281:     parts.next()?; // pid：不参与排序
282:     parts.next()?.parse().ok()
283: }
284: 
285: /// 保留**第一份 + 最近两份**，其余连同 `-wal/-shm/-journal` 一起清掉。
286: ///
287: /// `newest` 是刚隔离出来的那一份，无条件保留（即使它的 stamp 因时钟回拨排不进最新两份）。
288: fn prune_quarantined(newest: &Path, name: &str) {
289:     let Some(dir) = newest.parent() else { return };
290:     let prefix = format!("{name}.corrupt-");
291:     let Ok(entries) = fs::read_dir(dir) else { return };
292:     let mut found: Vec<(u128, PathBuf)> = entries
293:         .flatten()
294:         .filter_map(|entry| {
295:             let file_name = entry.file_name().to_string_lossy().into_owned();
296:             // 附属件跟着主件走，不作为独立候选。
297:             if ["-wal", "-shm", "-journal"]
298:                 .iter()
299:                 .any(|suffix| file_name.ends_with(suffix))
300:             {
301:                 return None;
302:             }
303:             let stamp = quarantine_stamp(&file_name, &prefix)?;
304:             Some((stamp, entry.path()))
305:         })
306:         .collect();
307:     if found.len() <= QUARANTINE_KEEP {
308:         return;
309:     }
310:     // 新 → 旧；同一毫秒按文件名倒序（counter 大的更新）。
311:     found.sort_by(|a, b| {
312:         b.0.cmp(&a.0)
313:             .then_with(|| b.1.file_name().cmp(&a.1.file_name()))
314:     });
315: 
316:     // 保留集：刚隔离的一份 + 最早的一份（首次损坏现场）+ 最新的若干份补足上限。
317:     let mut keep: HashSet<PathBuf> = HashSet::new();
318:     keep.insert(newest.to_path_buf());
319:     if let Some((_, oldest)) = found.last() {
320:         keep.insert(oldest.clone());
321:     }
322:     for (_, path) in found.iter().take(QUARANTINE_KEEP - 1) {
323:         if keep.len() >= QUARANTINE_KEEP {
324:             break;
325:         }
326:         keep.insert(path.clone());
327:     }
328:     for (_, old) in &found {
329:         if keep.contains(old) {
330:             continue;
331:         }
332:         tracing::debug!(path = %old.display(), "清理过旧的损坏索引保留件");
333:         for suffix in ["", "-wal", "-shm", "-journal"] {
334:             let mut candidate = old.as_os_str().to_os_string();
335:             candidate.push(suffix);
336:             let _ = fs::remove_file(PathBuf::from(candidate));
337:         }
338:     }
339: }
